/* Owner: Core team | Purpose: DOM event routing, storage-event sync and boot | Reads: SaleSync core state | Writes: via shared core actions | Emits: core events | Listens: shared store | Test: open its portal and exercise the relevant screens. */
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;if(el.closest('form')&&el.type==='submit')return;try{act(el.dataset.action,el)}catch(err){toast(err.message||String(err),true)}});
document.addEventListener('change',e=>{const t=e.target;try{if(workspaceChange(t))return;if(t.dataset.change)return changed(t);if(t.id==='price-filter')view.priceMax=Number(t.value),render();else if(t.id==='rating-filter')view.rating=Number(t.value),render();else if(t.id==='stock-filter'||t.id==='mobile-stock')view.inStock=t.checked,render();else if(t.id==='mobile-category')view.category=t.value,render();else if(t.id==='mobile-price')view.priceMax=Number(t.value),render();else if(t.id==='sort-products')view.sort=t.value,render();else if(t.id==='checkout-voucher')view.checkoutVoucher=t.value,render();else if(t.id==='date-from')view.from=t.value,render();else if(t.id==='date-to')view.to=t.value,render()}catch(err){toast(err.message,true)}});
document.addEventListener('submit',async e=>{if(e.target.id==='store-search-form'){e.preventDefault();act('shop-search',{dataset:{id:e.target.dataset.store}});return}if(e.target.id==='modal-form'){e.preventDefault();if(view.modalBusy)return;view.modalBusy=true;$('#modal-btn').disabled=true;try{let cb=view.modalSubmit;guard(cb,'No active form');let data=Object.fromEntries(new FormData(e.target));let result=cb(data);if(result instanceof Promise)await result;closeModal();render()}catch(err){$('#modal-error').textContent=err.message||String(err)}finally{view.modalBusy=false;$('#modal-btn').disabled=false}return}if(e.target.id==='auth-form'){e.preventDefault();try{await authSubmit(Object.fromEntries(new FormData(e.target)))}catch(err){toast(err.message,true)}return}if(e.target.id==='search-form'){e.preventDefault();view.search=$('#global-search')?.value||'';view.category=$('#search-category')?.value||'All';view.seeMore=25;go('shop');return}if(e.target.id==='chat-form'){e.preventDefault();let text0=new FormData(e.target).get('text').trim(),thread=S.chats.find(c=>c.id===e.target.dataset.thread);guard(text0&&thread,'Message is empty');let target=thread.customerId===userId?ownerOfStore(thread.storeId):thread.customerId;guard(userId===thread.customerId||userId===ownerOfStore(thread.storeId),'Unauthorized chat');thread.messages.push({id:id('M'),by:userId,text:text0,time:now(),read:false});commit('chat.sent',{to:target,storeName:getStore(thread.storeId).name});return}});
document.addEventListener('input',e=>{let t=e.target;if(t.id==='global-search'){const x=t.value.toLowerCase(),s=$('#search-suggestions');if(!s)return;let matches=x.length>1?S.products.filter(p=>visible(p)&&p.name.toLowerCase().includes(x)).slice(0,5):[];s.classList.toggle('hidden',!matches.length);s.innerHTML=matches.map(p=>`<button data-action="product" data-id="${p.id}">${esc(p.name)} · ${money(p.price)}</button>`).join('')}});
let touchStart=null;document.addEventListener('touchstart',e=>{if(e.target.closest('.hero'))touchStart=e.touches[0]?.clientX||null},{passive:true});document.addEventListener('touchend',e=>{if(touchStart===null)return;let delta=(e.changedTouches[0]?.clientX||touchStart)-touchStart;touchStart=null;if(Math.abs(delta)>45&&route()==='home'){view.hero=(view.hero+(delta<0?1:S.banners.length-1))%S.banners.length;render()}},{passive:true});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.id==='store-directory-search'){e.preventDefault();act('store-search',{dataset:{}});return}if((e.key==='Enter'||e.key===' ')&&e.target.matches('.product-name[tabindex]')){e.preventDefault();act('product',e.target)}if(e.key==='Escape'){$('#console-side')?.classList.remove('open');$('#mask')?.classList.remove('on');$('[aria-controls="console-side"]')?.setAttribute('aria-expanded','false');$('#header-pop')?.replaceChildren();$('#search-suggestions')?.classList.add('hidden')}});
$('#close-modal').addEventListener('click',closeModal);$('#cancel-modal').addEventListener('click',closeModal);window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0)});window.addEventListener('storage',e=>{if(e.key===SaleSync.auth.key()){const next=SaleSync.auth.readUser();if(next!==userId){userId=next;render();}return}if(e.key===KEY){let fresh=migrate();if(fresh.revision!==S.revision){S=fresh;render();toast('Marketplace data updated in another tab')}}});
// Advancing hero and flash countdown does not mutate or reload user data.
setInterval(()=>{const timer=$('#flash-timer');if(timer)timer.textContent='Ends in '+flashTimer()},1000);
upgradeWorkspaceData(S);save();runHousekeeping();setInterval(()=>runHousekeeping(),30000);
document.addEventListener('visibilitychange',()=>{if(!document.hidden)runHousekeeping()});
document.addEventListener('click',e=>{if(!e.target.closest('#header-pop,[data-action="pop"]'))$('#header-pop')?.replaceChildren();if(!e.target.closest('.search-shell'))$('#search-suggestions')?.classList.add('hidden');if(!e.target.closest('.management-command'))$('.mgmt-findings')?.remove()});
document.addEventListener('focusout',e=>{const root=e.target.closest('.search-shell,.management-command,#header-pop');if(root&&!root.contains(e.relatedTarget)){root.querySelector('#search-suggestions')?.classList.add('hidden');root.querySelector('.mgmt-findings')?.remove();if(root.id==='header-pop')root.replaceChildren()}});
document.addEventListener('change',e=>{if(e.target.id==='sim-shipment')syncCourierOptions();if(e.target.dataset.recordFilter){view.recordFilters??={};const key=e.target.dataset.recordFilter;view.recordFilters[key]??={};view.recordFilters[key][e.target.dataset.field]=e.target.value;view.recordPages??={};view.recordPages[key]=0;render()}});

render();

// User input updates idle activity; intervals remain offline-only.
document.addEventListener('click',()=>SaleSync.auth.touch());document.addEventListener('keydown',()=>SaleSync.auth.touch());
setInterval(()=>{try{let raw=JSON.parse(localStorage.getItem(SaleSync.auth.key())||'null');if(!raw?.userId)return;const age=Date.now()-raw.lastActive;if(age>30*60*1000){SaleSync.auth.signOut('idle timeout')}else if(age>29*60*1000&&!window.__salesyncIdleWarned){window.__salesyncIdleWarned=true;toast('Session ends in one minute due to inactivity');}}catch{}},20000);
SaleSync.selectors={product:id=>getP(id),available:id=>available(id),rating:id=>rating(id),comparedCount:id=>S.compareCounts?.[id]||0,currentUser:()=>getUser(),compareList:()=>compareIds().map(getP).filter(Boolean)};
SaleSync.actions={dispatch:(name,d={})=>act(name,{dataset:d}),compareAdd:id=>compareAdd(id),compareRemove:id=>compareRemove(id),placeOrder,providerEvent,returnAdvance};

window.SaleSync.ready=true;

// Management command search: route to relevant records; no direct business mutations.
document.addEventListener('input',e=>{if(e.target.id!=='mgmt-global-search')return;const q=e.target.value.trim().toLowerCase();let host=e.target.parentElement;host.querySelector('.mgmt-findings')?.remove();if(!q||q.length<2)return;let matches=[];matches.push(...S.products.filter(p=>(p.sku+' '+p.name).toLowerCase().includes(q)).slice(0,4).map(p=>[p.name+' · '+p.sku,'Product Moderation']));matches.push(...S.orders.filter(o=>o.id.toLowerCase().includes(q)).slice(0,3).map(o=>[o.id,'Order Oversight']));matches.push(...S.users.filter(u=>(u.email+' '+u.name).toLowerCase().includes(q)).slice(0,3).map(u=>[u.name,'Users']));matches.push(...S.stores.filter(st=>st.name.toLowerCase().includes(q)).slice(0,3).map(st=>[st.name,'Seller Applications']));let box=document.createElement('div');box.className='mgmt-findings';box.style.cssText='position:absolute;top:54px;right:80px;min-width:270px;max-width:380px;background:white;color:#1c2943;border:1px solid #e2e7f0;box-shadow:0 11px 28px #111c4733;border-radius:11px;padding:9px;z-index:70';box.innerHTML=matches.length?matches.map(([title,page])=>`<button style="display:block;width:100%;border:0;background:#fff;text-align:left;padding:9px;cursor:pointer" data-action="mgmt-result" data-page="${esc(page)}">${esc(title)} <span style="float:right;color:#74819a">${esc(page)}</span></button>`).join(''):'<div style="padding:10px">No matching records</div>';host.append(box);});
